<?php
require "db.php";require "functions.php";need_role("student");$q=$pdo->prepare("SELECT id,title,category,description,location,priority,status,resolution_note,created_at FROM complaints WHERE student_id=? ORDER BY created_at DESC");$q->execute([(int)$_SESSION["user_id"]]);$rows=$q->fetchAll();$title="My complaints";require "layout.php";?>
<div class="page-heading"><div><div class="eyebrow">YOUR REPORT HISTORY</div><h1>My <span class="green">complaints.</span></h1><p>Track your reports and read staff updates.</p></div><a class="btn btn-primary" href="complaint.php">＋ New complaint</a></div><section class="panel"><div class="panel-heading"><div><h2>All your reports</h2><p><?=count($rows)?> report(s) found</p></div><span class="pill">Private view</span></div><?php if(!$rows):?><div class="empty"><h3>No complaints yet</h3><p>Submitted reports will appear here.</p></div><?php else:?><div class="table-wrap"><table><thead><tr><th>Complaint</th><th>Priority</th><th>Status</th><th>Submitted</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?=e($r["title"])?></b><div class="muted small"><?=e($r["category"])?> · <?=e($r["location"]?: "Location not specified")?></div><p class="table-desc"><?=e($r["description"])?></p><?php if($r["resolution_note"]):?><div class="note"><b>Staff update:</b> <?=e($r["resolution_note"])?></div><?php endif;?></td><td><?=e($r["priority"])?></td><td><?=status_badge($r["status"])?></td><td><?=e(date("M j, Y",strtotime($r["created_at"])))?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section><?php require "end.php";?>
